package net.civeira.phylax.features.oauth.scopes.domain.gateway;

import java.util.List;

import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationChallege;
import net.civeira.phylax.features.oauth.scopes.domain.ScopePermission;

/**
 * Domain port for scope approval flows.
 *
 * <p>
 * Determines which of the requested scopes require explicit user approval (mandatory or optional),
 * and persists the user's decision once collected.
 *
 * <p>
 * Implementations receive the full authentication context — tenant, username, client, completed
 * challenges and requested scopes — and return a list of {@link ScopePermission} describing each
 * scope that still needs approval. Scopes with {@code required = true} must be accepted; scopes
 * with {@code required = false} are optional.
 *
 * <p>
 * An empty return value means no approval is needed and the flow can continue uninterrupted.
 */
public interface ScopeApprovalGateway {

  /**
   * Returns the scopes that require the user's approval.
   *
   * <p>
   * The implementation compares the requested scopes against any previously stored consents and
   * returns only those that still need an explicit decision. Each entry carries a {@code required}
   * flag distinguishing mandatory from optional scopes.
   *
   * @param tenant tenant identifier
   * @param username authenticated username
   * @param clientId OAuth client identifier
   * @param requestedScopes scopes requested by the client
   * @param completedChallenges challenges already satisfied in this authentication flow
   * @return pending scopes requiring approval; empty list if none
   */
  List<ScopePermission> pendingApprovals(String tenant, String username, String clientId,
      List<String> requestedScopes, List<AuthenticationChallege> completedChallenges);

  /**
   * Persists the set of scopes the user has accepted.
   *
   * <p>
   * Called after the user submits the approval form. Only the scopes the user chose to accept
   * (mandatory ones are always included) are stored. Implementations should ensure idempotency.
   *
   * @param tenant tenant identifier
   * @param username authenticated username
   * @param clientId OAuth client identifier
   * @param acceptedScopes scopes the user explicitly accepted
   */
  void storeApprovedScopes(String tenant, String username, String clientId,
      List<String> acceptedScopes);
}
